import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $v_p(k)$ denote the exponent of the prime $p$ in the prime factorization of the integer $k$. A positive integer $n$ is called a $p$-factorial number if $n = v_p(m!)$ for some positive integer $m$. For a given prime $p={prime_p}$ and an integer $N={limit_N}$, find the sum of all positive integers less than $N$ that are not $p$-factorial numbers.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
p = rng.choice([2, 3, 5, 7, 11, 13])
# N needs to be large enough to require the DP solution
# and not just manual enumeration.
# The complexity is O(log_p(N)), so N can be quite large.
if p == 2:
    N = rng.randint(500, 5000)
elif p == 3:
    N = rng.randint(1000, 10000)
elif p == 5:
    N = rng.randint(2000, 20000)
else:
    N = rng.randint(5000, 50000)
return {'prime_p': p, 'limit_N': N}

    def verifier(assign):
p = assign['prime_p']
N = assign['limit_N']

# Basic validation
if not isinstance(p, int) or not isinstance(N, int):
    return False, None # Should be integers
if p < 2 or N < 2:
    return False, None # Constraints

# Check if p is prime
for i in range(2, int(p**0.5) + 1):
    if p % i == 0:
        return False, None # p must be prime

# c_i = (p^i - 1) / (p - 1) are the bases for the mixed radix system
c = [0]
c_val = 1
while c_val < N:
    c.append(c_val)
    if (N - 1) // p < c_val: # Avoid overflow
        c_val = c_val * p + 1
    else:
        break

k = len(c) - 1

# Get the base-c representation of N
D = []
temp_N = N
is_N_tail = True
for i in range(k, 0, -1):
    digit = temp_N // c[i]
    D.append(digit)
    if digit >= p:
        is_N_tail = False
    temp_N %= c[i]
D.reverse() # LSB to MSB

memo = {}
def dp(i, tight):
    """DP to calculate count and sum of p-tails with i digits"""
    if i == 0:
        return (1, 0)
    state = (i, tight)
    if state in memo:
        return memo[state]

    res_count = 0
    res_sum = 0
    limit = D[i-1] if tight else p - 1

    for digit in range(limit + 1):
        new_tight = tight and (digit == limit)
        rec_count, rec_sum = dp(i - 1, new_tight)

        res_count += rec_count
        res_sum += rec_sum
        res_sum += digit * c[i] * rec_count

    memo[state] = (res_count, res_sum)
    return res_count, res_sum

# The DP calculates sum of p-tails <= N
# D is MSB-to-LSB, so D[0] is for c_k. We need to reverse it for the DP.
D.reverse()
sum_of_tails_le_N = dp(k, True)[1]

# We need sum of positive p-tails < N
# n=0 is always a p-tail, but its sum is 0.
sum_of_tails_lt_N = sum_of_tails_le_N
if is_N_tail:
    sum_of_tails_lt_N -= N

total_sum_lt_N = (N - 1) * N // 2

answer = total_sum_lt_N - sum_of_tails_lt_N

# Difficulty check: N should not be too small
if N < 100:
    return False, None # Too easy to brute force

return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

